265:   function ability(mon) { return ABILITIES[speciesData(mon).ability] || {}; }
266:   function types(mon) { return speciesData(mon).types || ['Normal']; }
267:   function stageMultiplier(stage) { return stage >= 0 ? (2 + stage) / 2 : 2 / (2 - stage); }
268:   function statValue(mon, stat) {
269:     const baseStat = number(mon.stats?.[stat], 50);
270:     let value = baseStat * stageMultiplier(number(mon.stages?.[stat], 0));
271:     if (stat === 'spe' && mon.status === 'para') value *= .5;
272:     if (stat === 'atk' && mon.status === 'burn') value *= .5;
273:     return Math.max(1, value);
274:   }
275:   function changeStage(session, mon, stat, amount, targetName) {
276:     if (!mon || !amount) return;
277:     const def = ability(mon);
278:     if (amount < 0 && def.clearBody) return;
279:     const before = number(mon.stages[stat], 0);
280:     const after = Math.max(-6, Math.min(6, before + amount));
281:     if (before === after) return;
282:     mon.stages[stat] = after;
283:     session.message = `${memberName(mon)}'s ${stat.toUpperCase()} ${after > before ? 'rose' : 'fell'}!`;
284:   }
