292:     if (typeof bag[id] === 'number') bag[id] = Math.max(0, bag[id] + amount);
293:     else if (bag.items && typeof bag.items[id] === 'number') bag.items[id] = Math.max(0, bag.items[id] + amount);
294:     else bag[id] = Math.max(0, number(bag[id], 0) + amount);
295:   }
