443:     if (typeof UI !== 'undefined' && UI.close) UI.close();
444:     current = null;
445:     session.resolve(result);
446:     session.onEnd?.(result);
447:   }
448:   async function useItem(session, itemId, target) {
449:     const item = ITEMS[itemId];
450:     if (!item || itemCount(session, itemId) <= 0) return false;
451:     if (item.kind === 'ball') {
452:       if (!session.wild) { await message(session, 'You can’t catch a Trainer’s Pokémon!'); return false; }
453:       if (session.canCapture === false) { await message(session, 'You can’t catch Pokémon here!'); return false; }
454:       adjustItemCount(session, itemId, -1);
455:       if (typeof Sound !== 'undefined') Sound.sfx('ball');
456:       const wild = session.foes[session.foeActive[0]];
457:       const rate = number(speciesData(wild).catchRate, 45) * item.rate * (1 + (1 - wild.hp / wild.maxHp) * 2);
458:       if (Math.random() * 255 < rate || item.rate >= 255) {
459:         await message(session, `Gotcha! ${memberName(wild)} was caught!`);
460:         const captured = createMember(speciesOf(wild), wild.level, { hp:wild.hp, name:wild.name });
461:         if (session.party.length < 6) session.party.push(captured);
462:         else {
463:           const box = Array.isArray(session.state.pc) ? session.state.pc
464:             : Array.isArray(session.state.storage) ? session.state.storage
465:             : (session.state.storage = []);
466:           box.push(captured);
467:         }
468:         updateHud(session);
469:         await end(session, { outcome:'caught', captured });
470:       } else {
471:         await message(session, `Oh no! ${memberName(wild)} broke free!`);
472:       }
473:       return true;
474:     }
475:     if (!target) return false;
476:     if (item.kind === 'heal') {
477:       if (!alive(target)) return false;
478:       const amount = Math.min(target.maxHp - target.hp, number(item.heal, 0));
479:       if (!amount) return false;
480:       target.hp += amount;
481:     } else if (item.kind === 'revive') {
482:       if (alive(target)) return false;
483:       target.hp = Math.max(1, Math.floor(target.maxHp / 2));
484:     } else if (item.kind === 'cure' || item.kind === 'cure_one') {
485:       if (!target.status || (item.status && target.status !== item.status)) return false;
486:       target.status = null;
487:     } else if (item.kind === 'level') {
488:       if (target.level >= 100) return false;
489:       target.level++; refreshStats(target, true);
490:     } else return false;
491:     adjustItemCount(session, itemId, -1);
492:     updateHud(session);
493:     await message(session, `Used ${item.name} on ${memberName(target)}!`);
494:     return true;
495:   }
496:   async function openBag(session) {
